INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30f0297c-5a99-4eca-a1aa-63139ece0428', '8cd1702d-19d7-46e6-a60f-5523e7d9d9bf', 0, 'Telehealth E/M visits use an entirely separate leveling system unrelated to time or MDM');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3c4f610-6884-421d-966b-21ad34d3d675', '8cd1702d-19d7-46e6-a60f-5523e7d9d9bf', 1, 'The same underlying office/outpatient E/M code set and leveling criteria (time or MDM) generally apply to a telehealth visit as would apply to the equivalent in-person visit, with an appropriate modifier/place-of-service indicator identifying the encounter as telehealth, subject to applicable payer telehealth coverage policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb522079-2458-4b7f-9616-deaccb7353da', '8cd1702d-19d7-46e6-a60f-5523e7d9d9bf', 2, 'Telehealth visits are always billed at the lowest possible E/M level regardless of actual complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f54c156-3537-46ff-9481-37cd8c308c70', '8cd1702d-19d7-46e6-a60f-5523e7d9d9bf', 3, 'Telehealth visits can never be leveled using medical decision making, only time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cf194aa-a222-424d-8e58-4a10a2c785cc', 'ef5614cf-37cd-45b6-a388-df388b61cdb7', 0, 'Indicates the service was rendered via synchronous telemedicine using an interactive audio and video telecommunications system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e48579af-f207-452f-b24d-fbc3960ec995', 'ef5614cf-37cd-45b6-a388-df388b61cdb7', 1, 'Indicates a service was reduced in scope');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be025988-b736-445c-b5a0-cca72f5d7b0e', 'ef5614cf-37cd-45b6-a388-df388b61cdb7', 2, 'Indicates two surgeons performed the procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c1006eb-0008-425e-83b7-ff6dc6b9ce4f', 'ef5614cf-37cd-45b6-a388-df388b61cdb7', 3, 'Indicates the service was provided by an assistant surgeon');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de9fadf5-7371-42f3-9be0-60acf35c8cdf', 'dee7a7e9-2802-42f6-82a2-fd8ee76fdc91', 0, 'Audio-only and audio-video telehealth visits are always coded and reimbursed identically by every payer with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5552e013-f31b-4058-a8f8-7b67f4bc3b46', 'dee7a7e9-2802-42f6-82a2-fd8ee76fdc91', 1, 'Certain codes/modifiers and payer policies specifically address audio-only (telephone) E/M services, which may have different coverage, documentation, or code-selection requirements than a full audio-video telehealth visit — recognizing this distinction is relevant given divergent and evolving payer policy in this area');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9df5b6bf-669d-4acf-ae87-ac31255d0f22', 'dee7a7e9-2802-42f6-82a2-fd8ee76fdc91', 2, 'Audio-only services can never be billed under any circumstance, regardless of payer policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0dfb4071-de22-4997-8f01-3873987de283', 'dee7a7e9-2802-42f6-82a2-fd8ee76fdc91', 3, 'Audio-only telehealth applies only to behavioral health services, never general medical E/M visits');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23c50e65-d9ef-4612-a995-189e7219e854', 'e0e6188e-fc83-449a-a01d-ed947596b79f', 0, 'RPM has specific CPT codes capturing device setup/education, device supply, and clinician time spent reviewing/managing the collected physiologic data over a defined period — a billable clinical service structure, not merely a technology/data-integrity concept');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69b9dc41-f8cd-4d50-8245-877107589bac', 'e0e6188e-fc83-449a-a01d-ed947596b79f', 1, 'RPM is never separately billable under CPT regardless of physician time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a44d17b0-d463-4f70-ae1a-37a664a0551b', 'e0e6188e-fc83-449a-a01d-ed947596b79f', 2, 'RPM billing codes apply only to hospital inpatient settings, never ambulatory care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a7d066b-9a39-49aa-9450-0e6a09121c92', 'e0e6188e-fc83-449a-a01d-ed947596b79f', 3, 'RPM codes require the device to be surgically implanted to be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7cd169c1-f84b-4192-badf-87df177e1635', '6866d397-9b99-4df7-abb1-5f9180932e69', 0, 'CCM time may include any staff member''s time, including non-clinical administrative staff, counted without any specific documentation of activities performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c39277b-d9cd-4ac4-aabe-69fcd5e360e0', '6866d397-9b99-4df7-abb1-5f9180932e69', 1, 'CCM codes require counting clinical staff time spent on qualifying non-face-to-face care coordination activities (e.g., care plan development/revision, medication reconciliation, coordinating with other providers) over a calendar month, with specific documentation supporting the time and activities performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56306dd3-8e33-47c6-92cf-88f114fa9d8f', '6866d397-9b99-4df7-abb1-5f9180932e69', 2, 'CCM has no time-counting requirement at all; it is a flat per-patient-per-month fee regardless of activity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5eb1b4ad-f2eb-4856-b9f3-6f879e1121da', '6866d397-9b99-4df7-abb1-5f9180932e69', 3, 'CCM time can only be counted if performed by the billing physician personally, never by clinical staff under general supervision');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e396b64-7922-4c73-aaee-6a4f9d332765', '1450fd3b-9b62-41f8-a266-9ebfd7b6a6c7', 0, 'These codes capture a consultant''s time providing an assessment/opinion to a treating provider via telephone/internet/EHR, without a face-to-face patient encounter by the consultant — a distinct service structure from a traditional in-person or telehealth consultation involving direct patient contact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad6cb2d3-ecec-493f-bb1f-3a536336dedb', '1450fd3b-9b62-41f8-a266-9ebfd7b6a6c7', 1, 'Interprofessional consultation codes require the consultant to personally examine the patient in person');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13761c47-9bde-4380-a11d-198746e42817', '1450fd3b-9b62-41f8-a266-9ebfd7b6a6c7', 2, 'These codes are billed by the treating physician, never the consultant, for the treating physician''s own time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('986c44ae-8de9-4196-ab82-4b19473c942c', '1450fd3b-9b62-41f8-a266-9ebfd7b6a6c7', 3, 'Interprofessional consultation codes apply only to behavioral health conditions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3cff1b4-fa51-4a3a-9d00-274c2763cd3a', '3ee95638-d1fd-4ab9-8ee5-460719457290', 0, 'TCM codes capture services related to a patient''s transition from an inpatient/facility setting back to the community, including a required timely interactive contact and a face-to-face visit within a defined timeframe, along with care coordination activities during the transition period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c94d729b-9e70-4ab2-80f9-10548519e7c0', '3ee95638-d1fd-4ab9-8ee5-460719457290', 1, 'TCM codes apply only to a patient''s initial hospital admission, not discharge');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0029fd62-e6fb-4346-ab87-57ca1c263bd1', '3ee95638-d1fd-4ab9-8ee5-460719457290', 2, 'TCM services require no face-to-face visit component whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8afb328-d8c5-48c8-8977-4ba9066c88aa', '3ee95638-d1fd-4ab9-8ee5-460719457290', 3, 'TCM codes are billed by the discharging hospital, never the outpatient physician managing the transition');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('308385ab-44ed-4a47-adcf-5440f5bf625a', 'aaea008b-5882-41f3-824d-6ca74af03edc', 0, 'PCM and CCM are identical codes with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11103487-99ea-4321-8229-1eb585979465', 'aaea008b-5882-41f3-824d-6ca74af03edc', 1, 'PCM codes address care management for a SINGLE complex chronic condition (rather than CCM''s requirement of two or more chronic conditions), reflecting a distinct clinical scenario (e.g., a specialist managing one complex condition while primary care coordinates overall CCM)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0de95cca-2008-4aa6-be32-8ff7ac73dde1', 'aaea008b-5882-41f3-824d-6ca74af03edc', 2, 'PCM applies only to pediatric patients, never adults');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('497771e9-c4e1-4666-b7b8-acd73d3a25f7', 'aaea008b-5882-41f3-824d-6ca74af03edc', 3, 'PCM codes require in-person visits only, with no non-face-to-face time counted');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32238a78-93b6-472b-bee0-60eceff82e93', 'a27253b4-e5a2-4abd-9868-71f50f762845', 0, 'A specific brief communication technology-based service code exists for short (e.g., 5-10 minute) check-ins that don''t originate from a related E/M visit within a certain timeframe and don''t lead to one within 24 hours, distinct from a full telehealth E/M visit code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('416f6aa4-3c7f-4886-befc-39330261a033', 'a27253b4-e5a2-4abd-9868-71f50f762845', 1, 'Virtual check-ins are always billed using the identical code as a full office visit E/M service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f99058c9-a08a-4817-b7c3-56180c43dd8b', 'a27253b4-e5a2-4abd-9868-71f50f762845', 2, 'Brief virtual check-ins can never be separately billed under CPT');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2019b523-1cd5-4f17-a461-4c81b5e30311', 'a27253b4-e5a2-4abd-9868-71f50f762845', 3, 'Virtual check-in codes require the encounter to last at least 30 minutes to be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2becda1e-88ed-4878-8c7c-d058b55231e8', 'a2b127c7-8f41-4180-883e-ece8fe68bb50', 0, 'A specific online digital E/M code family exists, based on cumulative time spent over a 7-day period responding to the patient''s inquiry via a secure digital platform, distinct from an office visit or telephone-based E/M service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e86ac982-d9d2-482c-953f-b4d4bea6ceb6', 'a2b127c7-8f41-4180-883e-ece8fe68bb50', 1, 'Online digital messaging is never separately billable regardless of physician time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5be04f65-d415-49ad-8f7f-174515215e78', 'a2b127c7-8f41-4180-883e-ece8fe68bb50', 2, 'Online digital E/M services are billed using the same code as a routine office visit E/M');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0616573-a071-4a98-ac11-f1d9ef941278', 'a2b127c7-8f41-4180-883e-ece8fe68bb50', 3, 'Online digital E/M codes require a live, real-time video connection to be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1c46490-5891-4db1-9355-5147888e8a38', '1324d4ea-6b64-4392-85a7-5021804b63d2', 0, 'No specific time documentation is needed for any of these code families; a flat monthly fee applies regardless of actual time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3578d0a6-3267-41bb-be72-f2413c1e9f7c', '1324d4ea-6b64-4392-85a7-5021804b63d2', 1, 'Clear, contemporaneous documentation of the specific qualifying activities performed and the actual time spent (meeting the applicable code''s time threshold) is generally needed to support compliant billing of these time-based, often non-face-to-face code families');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0bbe087-b446-4e15-a45e-9ba72a06780d', '1324d4ea-6b64-4392-85a7-5021804b63d2', 2, 'Time documentation is required only for CCM, not for PCM, RPM, or online digital E/M codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd717bd6-5d48-414e-9913-4d4c3edee0c0', '1324d4ea-6b64-4392-85a7-5021804b63d2', 3, 'These codes can be billed based on an estimated ''typical'' time rather than actual time spent for each specific patient/period');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1d83c33-71d0-4ffa-87d7-a2c168a037e4', 'c7c8b2b8-091b-45bd-9fb9-9ad5e53a5e77', 0, 'CCM and PCM may potentially both be appropriately billed by different providers for the same patient during overlapping periods, since they address different scopes of care management (CCM for multiple chronic conditions overall, PCM for a single complex condition by a focused specialist) — though time/activities counted toward each shouldn''t be double-counted between the two services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30d376e1-9193-4ed2-914b-7eb736dac556', 'c7c8b2b8-091b-45bd-9fb9-9ad5e53a5e77', 1, 'Only one of CCM or PCM may ever be billed for a given patient, regardless of which provider is providing which type of care management');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3eb7b75c-1d6c-4aa6-bf4a-162ef9975d8e', 'c7c8b2b8-091b-45bd-9fb9-9ad5e53a5e77', 2, 'CCM and PCM must always be billed by the exact same provider, never split between primary care and a specialist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2dabab37-1ee0-4d61-aab9-b8a68df5e649', 'c7c8b2b8-091b-45bd-9fb9-9ad5e53a5e77', 3, 'Overlapping CCM and PCM billing is always fraudulent regardless of the actual scope of services provided by each provider');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b7018e6-c080-44f3-bff2-3d6186ff355e', 'af87f198-0efb-434f-8ac8-3b49e698f681', 0, 'Certain codes specifically capture prolonged clinical staff (rather than physician/QHP) time spent under physician supervision for specific service types, reflecting a genuinely different billing structure than the physician-time-based prolonged services add-on codes already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6d340ac-a8a6-441e-84d8-3474f8116a4e', 'af87f198-0efb-434f-8ac8-3b49e698f681', 1, 'Clinical staff time is never separately billable under any circumstance, regardless of supervision or activity type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a00b29b-4130-42d2-825f-1e03df2ac2dd', 'af87f198-0efb-434f-8ac8-3b49e698f681', 2, 'Prolonged clinical staff services are billed using the identical code as prolonged physician E/M service time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f06fe744-3396-4127-a622-0c6b68048a97', 'af87f198-0efb-434f-8ac8-3b49e698f681', 3, 'Clinical staff time only counts toward CCM, never any other code family');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69591554-79c6-457d-8b93-e679ba70aa7c', '7257f47b-5f4b-4f84-9a5a-dea5468105e9', 0, 'Incident-to billing rules govern whether/how services provided by auxiliary personnel (under appropriate physician supervision, as an incidental part of the physician''s own professional service) may be billed under the supervising physician''s own NPI, a concept relevant to several of the non-face-to-face and staff-performed services discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('930bae4a-9bfa-4d3f-b8b7-c76a734f656d', '7257f47b-5f4b-4f84-9a5a-dea5468105e9', 1, 'Incident-to billing applies only to surgical procedures, never any Medicine or E/M-adjacent service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77c6bbf9-ba62-4198-8be6-f9d0bbda9704', '7257f47b-5f4b-4f84-9a5a-dea5468105e9', 2, 'Incident-to billing eliminates any need for physician involvement or supervision whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b78fe2e7-ff68-4113-b1ad-53492dce103e', '7257f47b-5f4b-4f84-9a5a-dea5468105e9', 3, 'Incident-to billing rules are identical across all payers with zero variation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36ba6d04-f938-4217-989a-c270aba88df1', 'dd6ed6c9-be70-48ac-9ce1-289164e478c7', 0, 'Documentation should reflect the actual modality/circumstances of the encounter as it genuinely occurred (including the connectivity issue and modality change), since coding and modifier selection should reflect what actually happened during the encounter, not a modality that was originally planned but not fully carried out');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2398280-2100-4309-8e9c-56f792cd3609', 'dd6ed6c9-be70-48ac-9ce1-289164e478c7', 1, 'The visit is automatically voided and cannot be billed under any circumstance once any technical interruption occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('834fdd0f-884f-4acf-9d63-9de909c39134', 'dd6ed6c9-be70-48ac-9ce1-289164e478c7', 2, 'Only the audio-video portion may ever be considered for coding purposes, with the audio-only portion completely disregarded regardless of clinical content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98015697-ed28-472e-97aa-65d5f60530af', 'dd6ed6c9-be70-48ac-9ce1-289164e478c7', 3, 'Technical interruptions have no bearing on which modifier is appropriate to append');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f278d35c-6961-43c4-b3c0-a00f36a723f3', 'e1240219-a9e0-4df4-8486-5cf7b16b5418', 0, 'Assume all payers cover all telehealth services identically to in-person services, with no payer-specific verification ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('448353d8-e071-4435-b453-7017e974da22', 'e1240219-a9e0-4df4-8486-5cf7b16b5418', 1, 'Verify current, payer-specific telehealth coverage policy (which can vary and change over time) for the specific service/code being considered, rather than assuming a blanket, universal telehealth coverage rule applies across all payers and all time periods');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6226a922-f17a-4823-b82d-2ee6fe39661f', 'e1240219-a9e0-4df4-8486-5cf7b16b5418', 2, 'Telehealth coverage is permanently fixed and was never subject to any policy change once initially established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d512f57-1dab-478d-8ae4-c4a7d5e8e904', 'e1240219-a9e0-4df4-8486-5cf7b16b5418', 3, 'Only Medicare''s telehealth policy is ever relevant; commercial payer policy never needs separate verification');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ba73c64-7578-40d4-a6cc-a28551fbfdc8', '3d65c403-0211-4f6f-9aaa-f4773551acd1', 0, 'These codes capture a structured care model involving a primary care provider, a behavioral health care manager, and often a psychiatric consultant collaborating on a patient''s behavioral health treatment, generally billed based on time spent on care coordination/management activities over a defined period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b09246d7-e01f-4ed0-9027-7db7da6f4ff0', '3d65c403-0211-4f6f-9aaa-f4773551acd1', 1, 'BHI/CoCM codes require the patient to be seen exclusively by a psychiatrist, with no primary care or care manager role');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1089ca91-0ef8-454d-83db-05e9cd6e0fcd', '3d65c403-0211-4f6f-9aaa-f4773551acd1', 2, 'These codes are billed identically to a standard psychotherapy visit with no distinct time/structure requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94185fa1-14cd-4c43-9b1e-3a87fb525cd0', '3d65c403-0211-4f6f-9aaa-f4773551acd1', 3, 'BHI/CoCM codes apply only to inpatient psychiatric admissions, never outpatient primary care settings');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb8296c5-faa6-4dad-9c88-2a31d3cb95e5', 'b16d3ee1-3445-4a8f-915e-0352b3dc3b01', 0, 'No specific documentation beyond a general note referencing ''behavioral health'' is needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29add5f3-d7eb-474a-bd9c-86087914880e', 'b16d3ee1-3445-4a8f-915e-0352b3dc3b01', 1, 'Documentation should reflect the care manager''s time spent on qualifying activities (patient outreach, tracking in a registry, care plan revisions) and any psychiatric consultant caseload review, consistent with the same time/activity documentation principle already established for other non-face-to-face, time-based code families (CCM, PCM, RPM)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b812bcb-a6ff-4f98-a2dc-029b9306becc', 'b16d3ee1-3445-4a8f-915e-0352b3dc3b01', 2, 'CoCM codes require no time documentation since they are billed as a flat annual fee');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eaea9deb-9e14-4d17-a7c1-871b09cca398', 'b16d3ee1-3445-4a8f-915e-0352b3dc3b01', 3, 'Only the psychiatric consultant''s documentation matters; the care manager''s activities require no separate documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1aa2477c-6f49-408b-adb8-1c2addcb9fc3', '7a4694f6-c130-44b6-b011-20fadbb1773e', 0, 'ACP codes capture time spent by a physician/QHP discussing advance directives with a patient (and/or their family/surrogate), face-to-face, potentially including completion of relevant forms — a time-based code distinct from a general E/M visit, though it may be reported on the same date as an E/M service when both are separately performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66ad488f-d4a0-4029-ad1f-34ce919fe42f', '7a4694f6-c130-44b6-b011-20fadbb1773e', 1, 'ACP codes require the patient to already have a terminal diagnosis to be billable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9e354b7a-bd8d-4b8f-a360-3e4e796ca07f', '7a4694f6-c130-44b6-b011-20fadbb1773e', 2, 'ACP is never separately billable from a general E/M visit under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45e0222c-8c98-4310-940a-fd1da3d1ce62', '7a4694f6-c130-44b6-b011-20fadbb1773e', 3, 'ACP codes are time-based but require no minimum time threshold whatsoever');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50e9d382-0fa0-4b9c-9001-e598e4eec964', '81d9eac4-8619-4dc9-8682-d09273688712', 0, 'Documentation should support that the ACP discussion is a genuinely distinct, separately identifiable service (with its own time tracked) from the E/M visit''s own time/MDM-based work, since simply having a conversation that touches on advance directives briefly during a routine visit may not meet the ACP code''s specific time/content requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('519ab978-eb9c-4d2c-8fa6-5d0242785a44', '81d9eac4-8619-4dc9-8682-d09273688712', 1, 'ACP and E/M can never be billed on the same date under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06e5e280-a2ea-4943-a0b2-e0f7520b00fb', '81d9eac4-8619-4dc9-8682-d09273688712', 2, 'Any mention of advance directives during an E/M visit automatically qualifies for separate ACP billing regardless of time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4b5eb62-2384-428a-a611-83b1832a59a7', '81d9eac4-8619-4dc9-8682-d09273688712', 3, 'ACP codes require no minimum threshold of substantive advance-care-planning discussion content');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df774822-1584-4904-a47f-f09c5fdda68c', 'd377b428-3d9e-4f9a-8a85-5dc288b8d490', 0, 'Obstetric anesthesia has its own specific code(s) reflecting labor epidural/analgesia management, generally distinct from the general surgical anesthesia base-unit-plus-time structure used for most other anesthesia codes, often reflecting a different payment structure (e.g., some payers use a different methodology for obstetric anesthesia than standard time-based anesthesia billing)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('edcf185e-314c-492d-82ec-b2356db429fd', 'd377b428-3d9e-4f9a-8a85-5dc288b8d490', 1, 'Labor epidurals are coded identically to a general surgical anesthesia case using the same time-unit-based formula with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('021e1091-2c13-45ac-9768-d863ab7c72fc', 'd377b428-3d9e-4f9a-8a85-5dc288b8d490', 2, 'Labor epidural anesthesia is never separately billable under CPT');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2818eda-2084-4b06-bd31-6327544b501b', 'd377b428-3d9e-4f9a-8a85-5dc288b8d490', 3, 'Obstetric anesthesia codes apply only to cesarean delivery, never vaginal delivery');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67bcc842-7c98-4b15-a467-66da7fe56593', 'f71e5e1c-b426-4ff4-967d-56f94d2c68cb', 0, 'A specific code exists for anesthesia for cesarean delivery following planned vaginal delivery (reflecting the epidural conversion scenario), distinct from the code for a planned, primary cesarean delivery anesthesia service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da63d212-00c0-40c6-81a8-0faf7f6c4bf2', 'f71e5e1c-b426-4ff4-967d-56f94d2c68cb', 1, 'The same code is always used regardless of whether the cesarean was planned or converted from a labor epidural');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7fe22f0-7144-4c76-986c-24daf4fa2d2e', 'f71e5e1c-b426-4ff4-967d-56f94d2c68cb', 2, 'Cesarean delivery anesthesia is never separately coded from vaginal delivery anesthesia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdfe4264-b010-4141-9511-174f1d83a6ba', 'f71e5e1c-b426-4ff4-967d-56f94d2c68cb', 3, 'Anesthesia conversion scenarios in obstetrics are billed using the general surgical anesthesia unlisted procedure code exclusively');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd94265d-4ba9-4ace-822b-51d47aa90b39', '1260ee02-88a6-46bf-9d94-a45161d1e093', 0, 'A separately identifiable, medically necessary nerve block placed specifically for postoperative pain management (rather than as the primary anesthetic for the surgery itself) may be separately reportable in addition to the anesthesia code for the surgery, subject to correct modifier use and documentation of separate medical necessity/purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ef5c191-902f-45e9-87b3-e6657c6a7888', '1260ee02-88a6-46bf-9d94-a45161d1e093', 1, 'Nerve blocks are always bundled into the anesthesia code for the surgery with no separate reporting possible under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa59c807-6177-44ee-9ffc-6d6446817013', '1260ee02-88a6-46bf-9d94-a45161d1e093', 2, 'Nerve blocks can only be coded when performed instead of, never in addition to, general anesthesia for a procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28978289-244f-4fdf-8657-48947aac054b', '1260ee02-88a6-46bf-9d94-a45161d1e093', 3, 'Postoperative pain blocks are coded using the same code as the surgical procedure itself');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95a487a2-1b39-472e-985a-00ded1cf1c4a', '3c67ba34-40ca-4497-8632-dbb45bf32ddb', 0, 'Chronic pain management injection codes are found within the Surgery/Radiology-adjacent sections (reflecting the injection procedure itself, often with associated imaging guidance codes), structurally distinct from the Anesthesia section''s surgical anesthesia codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31377edc-656e-4bcf-8d85-a4674564cf82', '3c67ba34-40ca-4497-8632-dbb45bf32ddb', 1, 'All pain management injections are coded using the general anesthesia base-unit-plus-time formula');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05524b0c-860a-4862-919a-f6c064b36753', '3c67ba34-40ca-4497-8632-dbb45bf32ddb', 2, 'Pain management injections can never be separately coded from a surgical anesthesia service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('036e38cd-e58a-4672-8395-06dbdf8cd8e2', '3c67ba34-40ca-4497-8632-dbb45bf32ddb', 3, 'Epidural steroid injections and surgical labor epidurals are coded using the identical code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('166fe10f-f899-4e8f-8116-d33cf725a0f4', 'f5f20f32-a2d3-4c6c-8a29-854bfacabc27', 0, 'A separate radiological guidance code may be reportable in addition to the injection procedure code, when the specific injection code doesn''t already bundle guidance into its own descriptor — consistent with the general guidance-bundling principle already established for other image-guided procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd63c8e1-e9da-4a88-a19d-c9c5e0ebcebd', 'f5f20f32-a2d3-4c6c-8a29-854bfacabc27', 1, 'Imaging guidance is never separately reportable for pain management injections under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55a9a886-49bb-4ad0-9640-ac6bc966972c', 'f5f20f32-a2d3-4c6c-8a29-854bfacabc27', 2, 'Imaging guidance always requires a completely separate CPT code section unrelated to Radiology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f11983d5-dd1c-4cb3-a043-c29d873d4dfb', 'f5f20f32-a2d3-4c6c-8a29-854bfacabc27', 3, 'Guidance codes replace the need for the injection procedure code entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ef1caff-b3f9-48dd-8d0e-debcedd2c851', '635857da-2cdc-4681-b695-c38bfdb2ec46', 0, 'The same fundamental anesthesia coding structure (base units, time units, physical status modifiers, qualifying circumstances) applies regardless of the specific facility setting (hospital vs. ASC), though facility-specific billing/payment rules may differ');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cccb820-8e00-4fad-ac26-cc6b004e4a42', '635857da-2cdc-4681-b695-c38bfdb2ec46', 1, 'ASC-based anesthesia uses an entirely different code set unrelated to the standard CPT anesthesia codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6fa6b20-e14b-4f24-95db-4e4754d29296', '635857da-2cdc-4681-b695-c38bfdb2ec46', 2, 'Anesthesia is never separately billable when a procedure is performed at an ASC');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c72667fc-8288-4e25-8d2b-34fd2aac723b', '635857da-2cdc-4681-b695-c38bfdb2ec46', 3, 'Physical status modifiers apply only to hospital-based anesthesia, never ASC-based anesthesia');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d23d1de5-34e5-4f5d-bea1-8ecf7138578c', '352d374d-6880-4b05-bc73-c0945d545b53', 0, 'Moderate sedation provided by the proceduralist (rather than a separate anesthesia provider administering general anesthesia) is generally coded using the distinct moderate sedation code family (already discussed in Paper 1) based on total intra-service time, not the anesthesia-section base-unit-plus-time formula used for anesthesia-provider-administered general anesthesia/MAC');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('292b2ff9-f350-4853-bb3a-952f36d20e04', '352d374d-6880-4b05-bc73-c0945d545b53', 1, 'Moderate sedation and general anesthesia are always coded using the identical anesthesia-section codes with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eedabec5-383e-4487-b757-7087f4e2885e', '352d374d-6880-4b05-bc73-c0945d545b53', 2, 'Moderate sedation is never separately coded when performed by the proceduralist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0808d193-78f9-4fe3-8555-f9a4e28a697c', '352d374d-6880-4b05-bc73-c0945d545b53', 3, 'Time documentation is irrelevant to moderate sedation coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecb45a63-0ac9-4cbb-9740-dccdb3e34c69', 'ea522556-c096-42de-8294-d6850fa826e4', 0, 'When a nerve block serves as the primary anesthetic technique for the surgery itself (rather than a postoperative pain adjunct alongside a separate primary anesthetic), it is coded as the anesthesia service for that procedure, generally following the same base-unit/time-unit anesthesia coding structure as general anesthesia would for that same procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fd546f4-5fb8-4fb6-9da2-298a9917ddac', 'ea522556-c096-42de-8294-d6850fa826e4', 1, 'Nerve blocks used as a primary anesthetic are always coded identically to a postoperative pain block regardless of their role in the case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('063302b5-007a-4bf8-acae-e214693a3084', 'ea522556-c096-42de-8294-d6850fa826e4', 2, 'A nerve block can never serve as the primary anesthetic technique for a surgical procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10bde21f-e54b-4c4a-a43b-0d9392536da9', 'ea522556-c096-42de-8294-d6850fa826e4', 3, 'Primary anesthetic nerve blocks are coded using only the Surgery-section injection codes, never the Anesthesia-section codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d313255-d6a6-41a3-939b-334b371c5eb8', '975840bc-ffa9-415b-a043-c4d76d1188ff', 0, 'The general anesthesia code for the procedure is reported, and the postoperative pain block may be separately reportable (via the appropriate Surgery-section nerve block code) if it is medically necessary, distinct in purpose from the general anesthetic itself, and appropriately documented — consistent with the general ''distinct, separately medically necessary purpose'' principle already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98aa6834-32dc-460e-b71a-3c728fc5c093', '975840bc-ffa9-415b-a043-c4d76d1188ff', 1, 'Only one of the two services may ever be coded, regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76e4a45e-57ee-4406-9ebd-6315ae2d16f4', '975840bc-ffa9-415b-a043-c4d76d1188ff', 2, 'The nerve block is always considered part of the general anesthesia code with no separate reporting possible under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c968bc6e-2084-41d1-9261-55cd0b136b69', '975840bc-ffa9-415b-a043-c4d76d1188ff', 3, 'General anesthesia and a postoperative nerve block can never both be performed for the same surgical case');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('913890e4-f43f-4c41-ba68-ed20bbefcf8c', 'c6ad8cb4-4645-4df2-887c-8ac52ca19857', 0, 'Documentation should reflect the block''s distinct purpose (postoperative pain management, not serving as the primary surgical anesthetic), who performed it, and that it was medically necessary and separately identifiable from the primary anesthesia service — consistent with the documentation-support principle already established generally for distinctly reportable services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3a03c22-7f7a-47cb-9882-078b940b904d', 'c6ad8cb4-4645-4df2-887c-8ac52ca19857', 1, 'No specific documentation is needed since postoperative pain blocks are always automatically separately billable regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37c0ef32-f178-4ef8-a027-c82a34915f75', 'c6ad8cb4-4645-4df2-887c-8ac52ca19857', 2, 'Only the block''s CPT code needs to be listed, with no supporting documentation of purpose ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6c5d7d9-0275-43f2-8351-b6f8bb251b27', 'c6ad8cb4-4645-4df2-887c-8ac52ca19857', 3, 'Postoperative pain block documentation requirements are identical to general anesthesia documentation requirements with no distinct elements');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb9aad1f-bfe1-4080-a39a-4ed39598170c', '1dd648f1-62e6-40fc-8535-b293bff25f9a', 0, 'Simple, intermediate, and complex repair — reflecting increasing depth/complexity of the repair technique required, from superficial closure to layered closure to more extensive reconstructive techniques');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9de8cf0-3639-443b-beef-0c354669b692', '1dd648f1-62e6-40fc-8535-b293bff25f9a', 1, 'Minor, major, and critical repair');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3075140e-3592-4333-9e39-2e83e399774f', '1dd648f1-62e6-40fc-8535-b293bff25f9a', 2, 'Type 1, Type 2, and Type 3 repair');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3542eb2a-3883-4d31-84e5-19b44375bfe7', '1dd648f1-62e6-40fc-8535-b293bff25f9a', 3, 'Elective, urgent, and emergent repair');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fbd7bd1-6c0c-4752-93d0-090c47dc140f', 'ec61fd17-6502-454a-a438-f5701d313df5', 0, 'Repair involving only the epidermis, dermis, or subcutaneous tissue, requiring simple one-layer closure with no significant exploration/debridement of the wound beyond what''s needed for the closure itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44c727ef-3d38-4750-bbcb-9c9aefa1ba17', 'ec61fd17-6502-454a-a438-f5701d313df5', 1, 'Repair requiring layered closure of one or more of the deeper layers of subcutaneous tissue and fascia in addition to skin closure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e653ca7-8bb6-47cb-ab7e-ce7549095a72', 'ec61fd17-6502-454a-a438-f5701d313df5', 2, 'Repair requiring extensive debridement, retention sutures, and complex reconstructive techniques');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8989a7ff-0c39-4d8e-b3e3-c2c39da78b96', 'ec61fd17-6502-454a-a438-f5701d313df5', 3, 'Repair performed only on facial lacerations, regardless of depth');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('835c9a98-5923-420a-832c-4524caf8de07', '7bf17aab-9197-4ffc-aeb0-bd0b0af0eaa3', 0, 'Repair requiring layered closure of one or more of the deeper layers of subcutaneous tissue and superficial (non-muscle) fascia, in addition to the skin (epidermal/dermal) closure — or a single-layer closure of a heavily contaminated wound requiring extensive cleaning/removal of particulate matter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa58f851-e222-45f4-b563-4d0576eb2ce1', '7bf17aab-9197-4ffc-aeb0-bd0b0af0eaa3', 1, 'Repair involving only a single layer of skin closure with no deeper tissue involvement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57eaf889-32e2-4cc5-885a-75ea9723e22e', '7bf17aab-9197-4ffc-aeb0-bd0b0af0eaa3', 2, 'Repair requiring scar revision or extensive undermining, retention sutures, or debridement of complex lacerations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4128cd7f-6298-4f43-9bc8-cc9a6e8d3420', '7bf17aab-9197-4ffc-aeb0-bd0b0af0eaa3', 3, 'Repair that never involves any wound cleaning or debridement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e305c5f6-f970-44d8-a737-5a10dd041e7e', '3c97b52d-5335-4d45-aace-4012303b29ec', 0, 'Repair requiring more than layered closure — such as scar revision, debridement (e.g., traumatic lacerations or avulsions), extensive undermining, stents, or retention sutures — reflecting the most extensive repair category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1aee47dc-22f2-4fdc-9d8e-53afcd6fdd3c', '3c97b52d-5335-4d45-aace-4012303b29ec', 1, 'Repair involving only simple one-layer skin closure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('329d1f4c-868b-4424-a796-1e0b4b2d58b2', '3c97b52d-5335-4d45-aace-4012303b29ec', 2, 'Repair that never requires any anesthesia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('888bbaeb-c98b-4aac-93ea-50a68b42d10b', '3c97b52d-5335-4d45-aace-4012303b29ec', 3, 'Repair defined solely by the length of the laceration, regardless of technique');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec4efb2c-ad51-4ef7-99d3-90024f162352', 'ee2d708c-402a-4f7d-adf3-a93bed321832', 0, 'The lengths of wounds within the same classification and anatomic grouping are generally added together and reported as a single code reflecting the total combined length, rather than reporting each wound with a separate code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d55396d-f984-43d0-b02e-b47fe9d538a5', 'ee2d708c-402a-4f7d-adf3-a93bed321832', 1, 'Each wound is always coded completely separately regardless of classification or anatomic grouping');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62d5845a-f9ff-4256-b912-fcfe3701fc93', 'ee2d708c-402a-4f7d-adf3-a93bed321832', 2, 'Only the longest single wound is coded, with shorter wounds in the same session disregarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d698eea-833f-41e6-9759-1ea185d219c8', 'ee2d708c-402a-4f7d-adf3-a93bed321832', 3, 'Wound repair codes are never based on length in any way');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be599bef-5a92-4ed7-b45f-4f653688a420', 'bfb3252b-169a-4bb3-87a9-e2c9f6ed67e2', 0, 'Each wound classification is coded and reported separately (with its own appropriate code, and modifier 51 or other multiple-procedure convention as applicable), since the length-summing convention applies only WITHIN the same classification, not across different classifications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd675e43-d1b4-460b-ac04-65ccb098f6b7', 'bfb3252b-169a-4bb3-87a9-e2c9f6ed67e2', 1, 'All wounds regardless of classification are always summed into a single code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b23e3b38-6772-4816-960d-daadf4bde17a', 'bfb3252b-169a-4bb3-87a9-e2c9f6ed67e2', 2, 'Only the most complex repair classification is coded, with simpler repairs at the same encounter disregarded entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f052bf9b-2b0f-4cbc-ae8b-803d3fef47de', 'bfb3252b-169a-4bb3-87a9-e2c9f6ed67e2', 3, 'Different classifications can never both be coded for the same patient on the same date');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66d6a909-351e-413f-8f67-f05d8c3260fe', 'd059ddba-9d42-4b25-8219-163449a891bc', 0, 'Margin width has no bearing on CPT code selection for malignant lesion excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d9e1422-56d7-402e-970e-d13e06a2a26c', 'd059ddba-9d42-4b25-8219-163449a891bc', 1, 'CPT malignant lesion excision codes are selected based on the lesion''s diameter PLUS the margin required for complete excision (the excised diameter), meaning documented margin width directly affects which specific code applies — a frequently tested integumentary coding detail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46256d1e-289e-409a-ab1f-07e73e537c5b', 'd059ddba-9d42-4b25-8219-163449a891bc', 2, 'Only benign lesion excisions consider margin width; malignant lesion excision codes ignore margins entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf718f08-ffbe-4303-a2bd-5417d89900d7', 'd059ddba-9d42-4b25-8219-163449a891bc', 3, 'Margin documentation is relevant only for pathology reporting, never for CPT procedure code selection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a818e788-a724-4946-b7e7-304becc3c9c8', 'f963bd9e-308c-4fe0-b901-d30d1439b4d9', 0, 'The excision code and the appropriate repair code (intermediate, complex, or an adjacent tissue transfer/flap code, depending on technique) may both be separately reportable, since simple closure is generally bundled into excision codes but more extensive repair techniques are not — mirroring the same bundling-versus-separately-reportable principle already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f23f9172-e3ec-47e4-a69c-2da38080d454', 'f963bd9e-308c-4fe0-b901-d30d1439b4d9', 1, 'Only the excision code is ever reported, regardless of how complex the resulting closure was');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b052b48e-e12e-4445-b74f-9f5cf3598161', 'f963bd9e-308c-4fe0-b901-d30d1439b4d9', 2, 'The repair is always bundled into the excision code regardless of technique complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b3d643e-8e14-4b43-a236-bf1c6ef2c7fc', 'f963bd9e-308c-4fe0-b901-d30d1439b4d9', 3, 'Excision and repair can never both be coded for the same lesion site');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a820461-b3cf-467a-b80d-1242dfd1b54c', '295a25f6-3f8f-4616-afc6-00222a5ac8a4', 0, 'Adjacent tissue transfer codes are used when a defect is closed by transferring/rearranging nearby tissue (rather than simple direct closure or a skin graft from a distant site), and these codes account for BOTH the primary defect and the secondary defect created by the transfer, using a total area calculation distinct from simple wound-length-based repair coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed8ce5bb-b58e-43cd-819c-40bb659d8eea', '295a25f6-3f8f-4616-afc6-00222a5ac8a4', 1, 'Adjacent tissue transfer is coded identically to simple wound repair, using the same length-based convention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('023ba7ae-a4cc-4c9e-8827-2af12bf7f9e8', '295a25f6-3f8f-4616-afc6-00222a5ac8a4', 2, 'Adjacent tissue transfer applies only to burn reconstruction, never routine lesion excision defects');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67d438e0-6974-4437-9f1d-035384a967bf', '295a25f6-3f8f-4616-afc6-00222a5ac8a4', 3, 'Adjacent tissue transfer codes are selected based on patient age rather than defect size');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df3f5e8e-e20c-400d-ace5-67eb7b0f25f2', '0a7f9546-9a7a-4567-ae43-1f6c3b2dc7a7', 0, 'Per CPT''s wound repair convention, single-layer closure of a heavily contaminated wound requiring EXTENSIVE cleaning/removal of particulate matter may be classified as intermediate repair (rather than simple repair), even without a true layered closure, reflecting the additional work involved in the contamination removal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4bcc699a-2e16-4838-8e77-bbef53c5b07f', '0a7f9546-9a7a-4567-ae43-1f6c3b2dc7a7', 1, 'This scenario is always classified as simple repair regardless of the extent of contamination/debris removal, since only one layer is closed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e946d02-8915-4dd2-b1d7-db17a7bc5bb0', '0a7f9546-9a7a-4567-ae43-1f6c3b2dc7a7', 2, 'Contamination level and debris removal have no bearing on repair classification under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba8854d8-0101-4490-b378-6b98e42cfd2e', '0a7f9546-9a7a-4567-ae43-1f6c3b2dc7a7', 3, 'This scenario is always classified as complex repair regardless of the extent of contamination');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('035e9f84-7673-4b50-8e2b-ed1f8b2a368f', '8cd7e491-22c1-4b5b-a4a2-9e7d53b5b5e9', 0, 'Benign lesion excision codes are structurally similar to malignant lesion excision codes (based on excised diameter including margin), but exist as their own distinct code family/category reflecting the different (benign vs. malignant) pathology, generally with different code values than the malignant lesion excision codes for a comparably-sized lesion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4eadf432-9c05-4b54-b60a-e7fa2d15afb9', '8cd7e491-22c1-4b5b-a4a2-9e7d53b5b5e9', 1, 'Benign and malignant lesion excisions are always coded using the exact same codes with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75dadace-df7e-4446-b2ef-6b9d88180b2b', '8cd7e491-22c1-4b5b-a4a2-9e7d53b5b5e9', 2, 'Benign lesion excision is never separately coded from a skin biopsy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf0e513e-030e-4140-ab95-57ae6ae39a34', '8cd7e491-22c1-4b5b-a4a2-9e7d53b5b5e9', 3, 'Benign lesion excision codes are based on the lesion''s weight in grams, not diameter');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3818f4c6-998c-4f11-82da-acc18fa33359', 'ba0583be-486f-4ead-8b84-8107842be07e', 0, 'The final, definitive pathology result (malignant) should generally govern code selection (benign vs. malignant lesion excision code family) once available, consistent with the general principle that coding incorporates the most definitive diagnostic information available, similar to how GI polyp pathology findings were treated earlier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7eb87b7b-8e9b-4113-abea-bc70c1ea63d8', 'ba0583be-486f-4ead-8b84-8107842be07e', 1, 'The excision must always be coded as benign since that was the only diagnosis documented before the procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('187488bd-437f-48a1-820b-a3bd43e4ca4b', 'ba0583be-486f-4ead-8b84-8107842be07e', 2, 'Pathology results are never relevant to selecting between the benign and malignant lesion excision code families');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ff83d80-c2f1-4534-a26d-cfc21fe508ef', 'ba0583be-486f-4ead-8b84-8107842be07e', 3, 'The excision cannot be coded at all until the surgeon personally amends the operative note with the pathology result restated verbatim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a46a6f89-8004-43a9-9f0b-3a7dc5e3b096', '57e6c19e-c46e-48a0-ad88-ea4bf2ac3d18', 0, 'Each lesion excision is generally coded and reported separately (each based on its own excised diameter), since — unlike the wound-repair length-summing convention — lesion excisions are not summed together into a single combined code, consistent with how this was already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4acb76a-cacb-44dc-877f-814b72692868', '57e6c19e-c46e-48a0-ad88-ea4bf2ac3d18', 1, 'All lesions are summed into a single combined-diameter code, mirroring the wound repair convention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c20c8f3c-727c-4a14-942f-cd6307c50ed8', '57e6c19e-c46e-48a0-ad88-ea4bf2ac3d18', 2, 'Only the largest lesion is coded, with smaller lesions excised at the same session disregarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2e141f8-1524-48d3-8f8a-59b2f6c8dd84', '57e6c19e-c46e-48a0-ad88-ea4bf2ac3d18', 3, 'Multiple lesion excisions can never be coded for the same patient on the same date');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3e79963-cfe0-4314-b79a-52bcbe1d595c', '4214f2fa-f025-4e8b-ac30-e210a6fbec2e', 0, 'Shave removal is a distinct, shallower technique (removing the lesion without a full-thickness through-the-dermis excision, and without a wound requiring suture closure) with its own specific code family, distinct from excision codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da6d5b1a-51f2-4bd5-8c9a-003076293a5b', '4214f2fa-f025-4e8b-ac30-e210a6fbec2e', 1, 'Shave removal is coded identically to a full excision, with no distinct code family');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6b61720-8cf4-41ec-87d8-740fadc4928c', '4214f2fa-f025-4e8b-ac30-e210a6fbec2e', 2, 'Shave removal always requires layered closure and is coded as an intermediate repair');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b31a09c-86a2-40f3-993c-b0cd389bae00', '4214f2fa-f025-4e8b-ac30-e210a6fbec2e', 3, 'Shave removal codes are based on excised diameter using the same formula as excision codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('643fe633-c160-43cd-bc6d-7eed9a8f493f', '0f9e300f-3bdc-4d5c-9901-cac1f849ad1c', 0, 'Destruction of premalignant lesions like actinic keratoses generally has its own specific code(s), often based on the NUMBER of lesions treated, reflecting a units-based (rather than diameter-based) coding structure distinct from excision or shave removal codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b66702a-1f50-4452-b546-d3ea263412d7', '0f9e300f-3bdc-4d5c-9901-cac1f849ad1c', 1, 'Actinic keratosis destruction is coded identically to a malignant lesion excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84e5b4bb-97b9-4201-a39c-bbf1d7afeb2a', '0f9e300f-3bdc-4d5c-9901-cac1f849ad1c', 2, 'Destruction procedures are always coded based on total body surface area treated, not number of lesions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('272dc9bd-be2e-416e-8711-1c44a808ccda', '0f9e300f-3bdc-4d5c-9901-cac1f849ad1c', 3, 'Cryosurgical destruction of skin lesions has no distinct CPT code, requiring an unlisted procedure code in all cases');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('51a50785-81ea-4342-9016-a7dc4c0e479d', '2a49a158-0789-4d54-9554-8d35c3ddb11a', 0, 'Skin graft codes are generally selected based on graft type (split-thickness vs. full-thickness, autograft vs. allograft/xenograft) and the size (area) of the defect/graft, reflecting a distinct code structure from both wound repair (length-based) and adjacent tissue transfer (different area-based) conventions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e9d5cb6-0631-4ef0-b2a2-df0bea39850b', '2a49a158-0789-4d54-9554-8d35c3ddb11a', 1, 'Skin grafts are coded identically to adjacent tissue transfer/flap procedures with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50911bb9-40d7-4276-96f0-533fa3eb9d3b', '2a49a158-0789-4d54-9554-8d35c3ddb11a', 2, 'Skin graft codes are based solely on the patient''s total body surface area burned, regardless of the actual graft site/size');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04e53b52-6bba-4335-a12b-d91491269648', '2a49a158-0789-4d54-9554-8d35c3ddb11a', 3, 'All skin graft types (autograft, allograft, xenograft) are coded identically regardless of graft source');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ba11ba1-4d3c-4f55-8931-7d655ade3b84', 'ec290488-8b50-406e-805f-d1cf81cb5902', 0, 'Both the lesion excision code (malignant lesion excision family, based on excised diameter) AND the appropriate skin graft code (based on graft type/area) may be separately reportable, since these represent genuinely distinct procedural components (excision of diseased tissue, then separate reconstructive closure via grafting) beyond what simple closure bundling would cover');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64e7a8ff-1ed4-45a4-a715-716be6c69164', 'ec290488-8b50-406e-805f-d1cf81cb5902', 1, 'Only the excision code is ever reported, with the graft considered bundled into it regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8963e1ee-63f8-4551-833b-89fe99aa00a3', 'ec290488-8b50-406e-805f-d1cf81cb5902', 2, 'Only the graft code is ever reported, with the excision considered bundled into it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07c026ef-ce34-41c7-a0d8-a49c45fee011', 'ec290488-8b50-406e-805f-d1cf81cb5902', 3, 'Excision and grafting can never both be coded for the same operative site in the same session');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffa60ec9-1de2-441c-9464-d8f23864ca8b', '40d51b4e-18b6-4100-9c7f-a68e9b2d804a', 0, 'Wound VAC application has its own specific CPT code(s), generally based on wound size/complexity and whether it''s the initial application or a subsequent dressing change, distinct from the excisional debridement codes already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecbd650b-0cf9-4945-a7b2-4070d1c1b8c4', '40d51b4e-18b6-4100-9c7f-a68e9b2d804a', 1, 'Wound VAC application is coded identically to excisional debridement regardless of whether tissue is actually excised');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('340fc21d-af9c-4c6c-b308-f9d80211fc07', '40d51b4e-18b6-4100-9c7f-a68e9b2d804a', 2, 'Wound VAC codes require documentation of a specific brand name device to be billable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b80e6aee-8f17-480a-a112-26f6541052a9', '40d51b4e-18b6-4100-9c7f-a68e9b2d804a', 3, 'Wound VAC application can never be separately coded from a routine wound dressing change');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2586fb2f-d658-4968-bcc6-3980a88c24a6', '81ef7c55-566f-495c-af83-a886084d8f48', 0, 'Both may potentially be separately reportable if each represents genuinely distinct, medically necessary work (debridement removing nonviable tissue, VAC application as a separate subsequent step), subject to correct modifier use and documentation supporting both as distinct components of the wound care encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e0ce2f9-7547-496c-b88f-cf56be757660', '81ef7c55-566f-495c-af83-a886084d8f48', 1, 'Only one of the two procedures may ever be coded for the same wound in the same encounter, regardless of documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bbf0092-7b45-4161-b67f-f8b73ad35054', '81ef7c55-566f-495c-af83-a886084d8f48', 2, 'Debridement and VAC application are always bundled into a single combined code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e409e05-812c-45fd-a84f-9e719a5dd99f', '81ef7c55-566f-495c-af83-a886084d8f48', 3, 'VAC application can never be performed in the same encounter as debridement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('687cbca4-906c-4f19-abbe-ddfc52797a9b', '6f1649a6-13b4-4d20-87ab-1a50f00206d4', 0, 'Removal of a subcutaneous implant has its own specific code, generally distinct from removal of a more deeply-placed device (e.g., a pacemaker), reflecting the specific anatomic location/technique involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e799af4d-8e36-4404-a699-8579a4f1edcc', '6f1649a6-13b4-4d20-87ab-1a50f00206d4', 1, 'All implant removals, regardless of location/depth, are coded using the identical single code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5adfb978-eaf1-4382-81ca-662e07401c01', '6f1649a6-13b4-4d20-87ab-1a50f00206d4', 2, 'Subcutaneous implant removal is coded using the same code as a skin biopsy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfd97989-c394-44b8-8469-d1bdfbe474f1', '6f1649a6-13b4-4d20-87ab-1a50f00206d4', 3, 'Implant removal is never separately coded from implant insertion');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e469d52b-9f7e-4bf2-a71d-655fa12142a9', '1f547ce8-4035-4580-bb67-8a46c4c96776', 0, 'CPT distinguishes simple/single I&D from complicated (e.g., requiring packing, multiple incisions, or multiple abscess sites) I&D with different codes reflecting the increased complexity, similar in concept to how wound repair and other integumentary procedures scale coding to documented complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b7b622a-6acd-4a90-a2a1-b0ff45990f14', '1f547ce8-4035-4580-bb67-8a46c4c96776', 1, 'All abscess I&D procedures are coded identically regardless of complexity or number of sites');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6de1ce6c-4cac-4a22-b2d6-ba0c41532f5c', '1f547ce8-4035-4580-bb67-8a46c4c96776', 2, 'I&D codes are based solely on the abscess''s anatomic location, with complexity never a coding factor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fae18175-3c0f-4c71-bf6a-456495ef3319', '1f547ce8-4035-4580-bb67-8a46c4c96776', 3, 'Only complicated I&D has a CPT code; simple I&D is never separately billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f863fdf-6fbc-4839-a28a-b795817a4d21', '6c253bd0-2dff-456e-85ea-a35c92ce4e32', 0, 'Excision of a pilonidal cyst (removing the cyst and its tract, often requiring more extensive tissue removal/complex closure) is coded distinctly from a simple I&D (which only opens and drains the abscess without removing the cyst/tract itself) — reflecting genuinely different procedures performed for the same underlying condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a779e53-c229-4cb5-b387-c4588a25df46', '6c253bd0-2dff-456e-85ea-a35c92ce4e32', 1, 'Excision and I&D of a pilonidal cyst are always coded identically regardless of which procedure was actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ee0846d-1146-4b75-94c3-7b0941f20929', '6c253bd0-2dff-456e-85ea-a35c92ce4e32', 2, 'Pilonidal cyst procedures are coded using the same codes as a routine skin abscess I&D regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('301f9854-c817-4e76-898a-e85c7a981606', '6c253bd0-2dff-456e-85ea-a35c92ce4e32', 3, 'Pilonidal excision can never be coded distinctly from an I&D under any CPT convention');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3eebe209-fd78-45b5-a342-63675791b5be', '3dcf7e7b-5fbe-4f57-97ff-ddf6ff4f5808', 0, 'The core needle biopsy procedure itself and the imaging guidance may each have their own specific codes (with guidance sometimes bundled into a combined code depending on the specific code selected), consistent with the general procedure-plus-guidance coding pattern already established for other image-guided procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13156629-d4a6-43fa-be22-7b4515bb466c', '3dcf7e7b-5fbe-4f57-97ff-ddf6ff4f5808', 1, 'Breast biopsy is always coded using an open surgical excisional biopsy code regardless of the actual technique (core needle) used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ff442ea-142a-4e08-b4fc-d66f3780bf1a', '3dcf7e7b-5fbe-4f57-97ff-ddf6ff4f5808', 2, 'Imaging guidance is never relevant to breast biopsy coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7ca1e16-ad0b-497d-ae77-baec91724180', '3dcf7e7b-5fbe-4f57-97ff-ddf6ff4f5808', 3, 'Breast core needle biopsy has no distinct code from a routine skin punch biopsy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4c930d2-e1cb-43f2-8ac7-03660138957f', '278c4055-6699-4be8-b392-bcc972da649c', 0, 'Sentinel lymph node biopsy has its own specific code, separately reportable from the primary breast excision/lumpectomy procedure code, since it represents a distinct additional procedure (nodal staging) beyond the primary breast tumor excision itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c48c1e1-d0fa-46b6-ba3e-2c876b6dfe5f', '278c4055-6699-4be8-b392-bcc972da649c', 1, 'Sentinel lymph node biopsy is always bundled into the lumpectomy code with no separate reporting possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87913352-e1d1-4a9b-bc2a-4125f844f713', '278c4055-6699-4be8-b392-bcc972da649c', 2, 'Sentinel lymph node biopsy is coded identically to a full axillary lymph node dissection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e44f0c6f-ed4c-40fa-85ab-d2ad5db02f8a', '278c4055-6699-4be8-b392-bcc972da649c', 3, 'Sentinel node biopsy can only be coded if performed as a completely separate, later encounter from the primary tumor excision');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('889170aa-e43d-4945-bec8-b5bf842dce46', '06ca933b-592a-407a-9270-72954dda192e', 0, 'CPT includes specific combined codes reflecting mastectomy WITH axillary lymph node dissection as a single procedure code, distinct from a simple/total mastectomy code that does not include axillary dissection — reflecting the same ''use the combined code when it accurately describes what was performed'' principle already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b75205e-d832-4042-b04d-f2be149e4181', '06ca933b-592a-407a-9270-72954dda192e', 1, 'Mastectomy and axillary dissection are always coded as two entirely separate codes with no combined-procedure code ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a786d6ee-8f6f-4d1d-a582-e1f4e71b49b8', '06ca933b-592a-407a-9270-72954dda192e', 2, 'Axillary lymph node dissection is never separately identified from a simple mastectomy in CPT''s code structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eed391c7-5320-4b59-94d4-47f3aaaa3759', '06ca933b-592a-407a-9270-72954dda192e', 3, 'All mastectomy types are coded using a single universal code regardless of whether axillary dissection was also performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('344bdc27-9542-45dc-8f29-fb75d07bcf0f', '5f727cc5-8325-46e4-b592-d3ed6349b8af', 0, 'Tissue expander placement has its own specific code, distinct from permanent implant placement, reflecting that a tissue expander is a temporary device used to gradually stretch tissue before a LATER, separate procedure to place the permanent implant or complete reconstruction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('016916b3-a275-4d06-a2f7-6067dbe8fe66', '5f727cc5-8325-46e4-b592-d3ed6349b8af', 1, 'Tissue expanders and permanent implants are coded identically since both are placed in the same anatomic location');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93bf9d45-639e-4136-b0b8-3d93b5c22495', '5f727cc5-8325-46e4-b592-d3ed6349b8af', 2, 'Tissue expander placement is never separately coded from mastectomy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd4befb3-c8bb-4f82-a26a-c431faa1abdc', '5f727cc5-8325-46e4-b592-d3ed6349b8af', 3, 'Only permanent implants have a CPT code; tissue expanders have no corresponding code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd49e88f-5c83-47a7-b784-1720572afae8', 'b7cdbf31-aab4-4b0b-882f-55262bed49e0', 0, 'This exchange procedure has its own specific code reflecting removal of the tissue expander and insertion of the permanent implant, distinct from the original tissue expander placement code and from a routine, non-staged initial implant placement code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59d9e8db-d30e-4257-9813-69bf1b92e858', 'b7cdbf31-aab4-4b0b-882f-55262bed49e0', 1, 'The exchange procedure is coded identically to the original tissue expander placement code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26ea2967-c841-4a0a-a363-afeb8a48f974', 'b7cdbf31-aab4-4b0b-882f-55262bed49e0', 2, 'The exchange procedure is coded as a simple device removal with no separate consideration for the new implant placement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa9ea6a2-e94a-46bc-b348-897d7a3b5f01', 'b7cdbf31-aab4-4b0b-882f-55262bed49e0', 3, 'Tissue expander exchange for a permanent implant has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbeb2dd7-fefb-41ca-aacd-7537ad3fa6dd', 'aa59c922-f10a-4b2b-97e9-d19545a43c14', 0, 'Excisional biopsy (surgically removing the entire mass, typically requiring an incision and closure) is coded distinctly from a core needle biopsy (a percutaneous needle-based sampling technique), reflecting genuinely different levels of surgical invasiveness and technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76b51ca0-fdb1-4971-9b15-069e0efc8026', 'aa59c922-f10a-4b2b-97e9-d19545a43c14', 1, 'Excisional and core needle biopsy of a breast mass are always coded identically regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb42c18a-a073-4e6d-9ffc-9ebbfbc30c1e', 'aa59c922-f10a-4b2b-97e9-d19545a43c14', 2, 'Excisional biopsy is coded using the same code as a mastectomy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49871fd1-0537-4038-b913-1ddebe18b050', 'aa59c922-f10a-4b2b-97e9-d19545a43c14', 3, 'Core needle biopsy of the breast has no distinct CPT code from a routine venipuncture');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a271e172-6ae9-4b7a-a908-e75ead96dbb6', '437f6a2d-8310-4941-b1a7-8159cd4e689c', 0, 'Always default to the simplest, lowest-complexity code available regardless of documented technique/extent, to minimize compliance risk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae682e42-ab60-4b5f-8621-3b9ec7e08932', '437f6a2d-8310-4941-b1a7-8159cd4e689c', 1, 'Carefully match the SPECIFIC documented technique, extent/size, and anatomic detail to the code descriptor that most accurately reflects what was actually performed — since CPT integumentary/breast coding repeatedly distinguishes codes based on these specific documented details rather than a generic ''procedure was performed'' description');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d77f7a5b-0463-4144-ac97-a9144425b975', '437f6a2d-8310-4941-b1a7-8159cd4e689c', 2, 'Assume all procedures within the same general body area (e.g., ''breast'' or ''skin'') are coded identically regardless of the specific technique used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44e6b2eb-606d-48a0-a734-ccad536a00e0', '437f6a2d-8310-4941-b1a7-8159cd4e689c', 3, 'Rely solely on the procedure''s CPT code number''s numeric proximity to a familiar code, without reviewing the actual descriptor');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('877b361a-55db-4355-8658-0f0795e52613', 'a242a901-81d2-4a5c-82e1-390ff9501eae', 0, 'The localization procedure and the lumpectomy/excision procedure may each have their own distinct code, or a combined code may apply depending on the specific CPT structure for the procedures actually performed, consistent with the general ''match the specific documented components to the code descriptor'' principle already established for breast and other Surgery-section procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75136e60-d4fd-41bf-a4a1-63e379617190', 'a242a901-81d2-4a5c-82e1-390ff9501eae', 1, 'Localization is always automatically bundled into the excision code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e028b408-a8a4-4e2f-ba0c-cf3f870681de', 'a242a901-81d2-4a5c-82e1-390ff9501eae', 2, 'Localization is coded identically to a diagnostic mammogram');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04945c77-430a-4525-9a1f-d53269d1afd8', 'a242a901-81d2-4a5c-82e1-390ff9501eae', 3, 'A non-palpable lesion excision can never be coded distinctly from a palpable lesion excision');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4904bc0-8742-4588-a8e4-a025083e5980', '859e79a7-775c-4e84-89c8-a4adee3aa5fa', 0, 'A nuclear medicine bone scan involves administering a radiopharmaceutical that concentrates in areas of bone turnover, imaged using a gamma camera — a functionally distinct imaging modality from plain-film/CT anatomic imaging, with its own distinct code family reflecting the radiopharmaceutical administration and imaging performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25c75d8c-6a4b-4a6f-bb1c-a6d10f9b4f40', '859e79a7-775c-4e84-89c8-a4adee3aa5fa', 1, 'Nuclear medicine bone scans are coded using the same codes as a plain-film bone X-ray');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a97ca45-3446-4b53-b6a8-9ae77cfa115f', '859e79a7-775c-4e84-89c8-a4adee3aa5fa', 2, 'Nuclear medicine imaging never requires a separate code from CT imaging of the same body area');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b06e0a8-1382-4511-94b2-436264abf184', '859e79a7-775c-4e84-89c8-a4adee3aa5fa', 3, 'Bone scans are coded based on the number of X-ray views obtained, identically to plain-film radiography');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebdeb2b5-648a-4610-8537-8996e9a9639a', '716abecc-edaf-4386-955d-2eec30ca9c04', 0, 'The radiopharmaceutical itself may be separately reportable (often via an appropriate HCPCS Level II supply code), in addition to the CPT code for the nuclear medicine imaging procedure itself, since the drug/tracer and the imaging service reflect distinct components of the overall study — mirroring the vaccine product/administration and contrast-material concepts already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('705af0c7-a438-45f7-b1de-bdcfcafea794', '716abecc-edaf-4386-955d-2eec30ca9c04', 1, 'The radiopharmaceutical is always included in the nuclear medicine procedure code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7eff71a3-2b97-4de3-9b55-32bec2c2b18e', '716abecc-edaf-4386-955d-2eec30ca9c04', 2, 'Radiopharmaceuticals are billed using the same CPT code as the imaging procedure itself, with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cbd6682-ed72-4345-a212-9b638d34b01a', '716abecc-edaf-4386-955d-2eec30ca9c04', 3, 'Radiopharmaceutical administration requires a completely separate anesthesia code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e7afaf2-9511-48f4-aad1-8ee4bd68d756', '15c5813c-e4b8-4e93-9f49-e92a71fccecf', 0, 'Screening and diagnostic mammography use completely identical codes with no distinction, regardless of the reason for the study');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58f1dec6-c311-4447-98d1-39cd09068716', '15c5813c-e4b8-4e93-9f49-e92a71fccecf', 1, 'CPT (and payer coverage policy) generally distinguishes screening mammography (routine, asymptomatic) from diagnostic mammography (performed to evaluate a specific sign/symptom or follow up an abnormal finding), each with its own applicable code(s) and coverage considerations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53febae2-3fb0-425f-a5f2-a97f641cfdce', '15c5813c-e4b8-4e93-9f49-e92a71fccecf', 2, 'Diagnostic mammography is never a separately identifiable service from screening mammography');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b0ea734-469f-4e6b-85a3-3afd599e3429', '15c5813c-e4b8-4e93-9f49-e92a71fccecf', 3, 'Mammography codes are selected based solely on patient age, with no distinction for screening vs. diagnostic purpose');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b555bd5f-8d48-438b-88ab-32b7b5f773af', 'a4a00087-edf8-47fe-a083-f16403e92fc1', 0, 'Coding should reflect what was actually performed — potentially both a screening component and additional diagnostic imaging, depending on payer policy and how the specific encounter unfolded — mirroring the general ''screening converted to diagnostic, code what was actually done'' principle already established for other modalities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('420f2648-8fa6-45ff-b993-df75128c8517', 'a4a00087-edf8-47fe-a083-f16403e92fc1', 1, 'Only the screening code is ever used, regardless of additional diagnostic views obtained');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f385be7e-9a6f-4291-be77-b016e81059d8', 'a4a00087-edf8-47fe-a083-f16403e92fc1', 2, 'Only the diagnostic code is ever used, with the screening component never separately reflected');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8385832f-a40c-4723-9d95-ff0c3d1f76a9', 'a4a00087-edf8-47fe-a083-f16403e92fc1', 3, 'This scenario can never occur under any circumstance, since screening and diagnostic mammography are always performed on separate days');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30cf910d-72fd-4830-8b61-55786eea26d4', 'd3fc0683-4a7e-4170-acfe-513b252ad065', 0, 'Tomosynthesis has its own specific add-on code(s) reflecting this distinct imaging technique, reported in addition to the base mammography code when tomosynthesis is performed alongside standard digital mammography');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09d5d4b8-5cfd-47d9-9ec9-719429e8d7d5', 'd3fc0683-4a7e-4170-acfe-513b252ad065', 1, 'Tomosynthesis is coded identically to standard 2D mammography with no distinct code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa7d614a-73db-4add-930c-930d32c030f2', 'd3fc0683-4a7e-4170-acfe-513b252ad065', 2, 'Tomosynthesis replaces the need for any base mammography code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f62141ca-ab21-411a-b7de-ea07fbee0eb9', 'd3fc0683-4a7e-4170-acfe-513b252ad065', 3, 'Tomosynthesis is coded using a nuclear medicine code, since it involves 3D imaging');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61b8bf84-3108-4952-b552-8c0a1c1a4dd7', '9aaf9238-9d48-4b57-874d-4d129572028f', 0, 'Combined PET/CT studies generally have their own specific combined code(s) reflecting the integrated study, rather than requiring the PET and CT components to always be coded as two entirely separate, unrelated procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93128f16-cd43-4029-970b-6d8570d48d6d', '9aaf9238-9d48-4b57-874d-4d129572028f', 1, 'PET and CT are always coded as two completely separate, unrelated procedures with no combined-study code ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cff86065-0420-4873-a8af-4b049737feda', '9aaf9238-9d48-4b57-874d-4d129572028f', 2, 'PET/CT studies are coded using the same code as a nuclear medicine bone scan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('974a3f8a-2235-4887-8874-ab4e5f4949a5', '9aaf9238-9d48-4b57-874d-4d129572028f', 3, 'PET/CT requires reporting the CT component using only the Radiology section, with the PET component entirely uncoded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72728df3-b307-436e-bc91-2face69b58f8', '015935d3-74b9-4c54-94e8-7fc9471e581e', 0, 'DEXA (dual-energy X-ray absorptiometry) uses low-dose X-ray technology to measure bone mineral density and has its own specific code(s), structurally and clinically distinct from a nuclear medicine bone scan (which uses a radiopharmaceutical to detect bone turnover/metabolic activity, not density)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ca7dfd4-8dc4-489d-a5d7-454ef605d991', '015935d3-74b9-4c54-94e8-7fc9471e581e', 1, 'DEXA and nuclear medicine bone scans are coded identically since both involve the skeletal system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5829ee2e-1158-404a-8d53-3bb22a0d2c20', '015935d3-74b9-4c54-94e8-7fc9471e581e', 2, 'DEXA scans require radiopharmaceutical administration, identical to a nuclear medicine bone scan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15510fcd-773f-41a5-a263-2ab0aed67954', '015935d3-74b9-4c54-94e8-7fc9471e581e', 3, 'Bone density studies have no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('621eb0fc-b54d-466a-ad04-19aa3c8ff05f', 'b07af758-a284-41b1-b697-8ad419ec499c', 0, 'This nuclear medicine study has its own specific code(s) reflecting both the uptake measurement and the imaging component, distinct from a thyroid ultrasound (which uses sound waves, not radiopharmaceutical uptake, to image the gland)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4de6a09-fc9d-42f8-a54f-3543a3360b67', 'b07af758-a284-41b1-b697-8ad419ec499c', 1, 'Thyroid uptake/scan and thyroid ultrasound are coded identically since both image the thyroid');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c7e489b-9946-429f-8e60-5baff94e89e8', 'b07af758-a284-41b1-b697-8ad419ec499c', 2, 'Thyroid uptake studies are coded using the same code as a PET scan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ec58b9e-3276-4c83-9488-1244bcc3a4a1', 'b07af758-a284-41b1-b697-8ad419ec499c', 3, 'Radioactive iodine uptake studies have no distinct code from a routine TSH blood test');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0e39bc3-563c-4802-94f8-23c4942d719c', '4a7df138-dfc7-4dc4-b6d9-9e51d563d24a', 0, 'Screening mammography and screening breast MRI are distinct modalities/services, each with its own appropriate code, and both may be separately reportable when both are genuinely, medically appropriately performed as part of a high-risk screening protocol');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7d93a50-b453-4f5d-9f9c-39a2e04b4f50', '4a7df138-dfc7-4dc4-b6d9-9e51d563d24a', 1, 'Only one imaging modality may ever be coded per encounter regardless of clinical indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6398d03c-718a-4760-bb63-b03c61cc2101', '4a7df138-dfc7-4dc4-b6d9-9e51d563d24a', 2, 'Screening MRI is always bundled into the mammography code with no separate reporting possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58f7d4f8-34c4-42b9-8abc-015778e8fbfa', '4a7df138-dfc7-4dc4-b6d9-9e51d563d24a', 3, 'High-risk screening protocols have no distinct coding considerations from routine screening');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('929c9d60-1847-4568-989e-5fb18cb8421d', '62e686b5-2dc8-4ee6-83a6-3e6da50f321e', 0, 'Always select the code for the most expensive/advanced imaging technology available, regardless of what was actually documented as performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72a687ab-c428-4b8b-b346-131e830d27cf', '62e686b5-2dc8-4ee6-83a6-3e6da50f321e', 1, 'Carefully match the specific imaging MODALITY (X-ray, CT, MRI, ultrasound, nuclear medicine), use of contrast, number of views, and combined-versus-component-study structure to the code descriptor that most accurately reflects the specific study actually performed and documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03ba9239-0696-4810-9eb0-32f719936528', '62e686b5-2dc8-4ee6-83a6-3e6da50f321e', 2, 'Assume all imaging of the same body part is coded identically regardless of modality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c29ae4ba-9c8e-41ea-a306-80162d0350bd', '62e686b5-2dc8-4ee6-83a6-3e6da50f321e', 3, 'Rely on the ordering physician''s requisition alone, without ever confirming what was actually performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b2ac9ce-29e5-45d1-a5b7-ec0f02782e79', 'c0c89b1c-aaa2-44be-92f8-d71a4c0a2445', 0, 'The culture (identifying the organism) and the sensitivity/susceptibility testing are generally distinct, separately identifiable code components within the Microbiology subsection, reflecting genuinely different laboratory processes (growing/identifying the organism vs. testing its antibiotic susceptibility)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1325f1b-e9cf-43dd-910e-1f5b020bf921', 'c0c89b1c-aaa2-44be-92f8-d71a4c0a2445', 1, 'Culture and sensitivity testing are always combined into one single code with no separate components ever identified');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45e6cd8d-9a70-449a-a531-c52454e01d36', 'c0c89b1c-aaa2-44be-92f8-d71a4c0a2445', 2, 'Sensitivity testing is never separately coded from the culture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df073e44-4bd6-4ad5-96b9-26f33c64f2fd', 'c0c89b1c-aaa2-44be-92f8-d71a4c0a2445', 3, 'Culture and sensitivity are coded using the same codes as a routine urinalysis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5fc49283-ec76-4dbb-b944-a77f0d0df5f1', '9fe4a770-f9ec-40dc-b81a-4e1b8185b526', 0, 'Presumptive identification (a preliminary, less specific identification method) and definitive identification (confirming the specific organism to the genus/species level via more specific testing) are coded distinctly, since they represent different levels of laboratory work/specificity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e82da58-263f-47bb-a581-02a73c68df64', '9fe4a770-f9ec-40dc-b81a-4e1b8185b526', 1, 'Presumptive and definitive identification are always coded identically regardless of the actual testing method used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f38eb11-e893-4830-8150-4d174547ac95', '9fe4a770-f9ec-40dc-b81a-4e1b8185b526', 2, 'Only definitive identification is ever coded; presumptive identification is never separately reportable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d839f5fd-44c3-424a-a3af-3310637cddb7', '9fe4a770-f9ec-40dc-b81a-4e1b8185b526', 3, 'The presumptive-versus-definitive distinction applies only to viral testing, never bacterial testing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59451c20-6ee1-4ef4-9349-047db33d24c0', '5f41dd00-560e-42eb-923a-c29f62451168', 0, 'Pap smear coding can involve distinct components for specimen screening/technical processing versus physician interpretation (particularly for abnormal or complex results requiring physician review), similar in concept to other pathology professional/technical component splits already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f57577e-7dfe-44c1-8190-743d5036ad18', '5f41dd00-560e-42eb-923a-c29f62451168', 1, 'Pap smears are always coded using a single, indivisible code regardless of screening method or whether physician interpretation was required');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ac4f71b-0116-42c9-9597-8e38db6fb35a', '5f41dd00-560e-42eb-923a-c29f62451168', 2, 'Pap smear coding has no relationship to any professional/technical component concept');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('271eca6e-7e79-4868-89e6-5754cdf76398', '5f41dd00-560e-42eb-923a-c29f62451168', 3, 'Only automated (never manual) Pap smear screening methods have any CPT code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aed38f7e-e3ef-49ba-976d-a58ea2e69ba7', 'c855dd9e-837d-47cf-b41d-c794403aaf06', 0, 'The specific screening method/technology used is a defining, code-selection-relevant detail within CPT''s cytopathology code structure, meaning documentation of the actual method used directly affects correct code assignment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11fd52a1-c597-4a3a-a534-5066947af2e6', 'c855dd9e-837d-47cf-b41d-c794403aaf06', 1, 'All Pap smear methods are coded identically regardless of the specific technology/screening method used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a98b863-4c2b-4a52-b5c3-fd5962438254', 'c855dd9e-837d-47cf-b41d-c794403aaf06', 2, 'Screening method is relevant only to laboratory accreditation, never to CPT code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('debac022-f123-47f4-a62a-97b6c4844623', 'c855dd9e-837d-47cf-b41d-c794403aaf06', 3, 'Liquid-based cytology has no distinct CPT code from conventional smear technique');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42435cd5-6b95-44b4-a156-52227af220da', '13bc931b-bde0-48e1-b1e2-007ec575557d', 0, 'FNA cytology involves its own specific code(s) within the Pathology & Laboratory (cytopathology) or Surgery section (for the aspiration procedure itself) reflecting cellular/cytologic sampling, structurally distinct from a surgical tissue biopsy''s Excision-based coding approach (in ICD-10-PCS) or CPT surgical biopsy codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d9622d0-3fd3-429b-baed-c45beff11238', '13bc931b-bde0-48e1-b1e2-007ec575557d', 1, 'FNA cytology is coded identically to a surgical excisional biopsy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3ab304b-8e45-41df-9192-abeb759bb7cd', '13bc931b-bde0-48e1-b1e2-007ec575557d', 2, 'FNA has no distinct CPT code from a routine blood draw');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76badea5-c129-48a8-b3f8-b330b4a5d0b5', '13bc931b-bde0-48e1-b1e2-007ec575557d', 3, 'FNA cytology can only be coded when performed on thyroid nodules, never other sites');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb015851-d0d2-4599-b849-47f327bef330', 'aa4c3f67-4bb9-4810-8da9-9192955bdf8f', 0, 'The Pap smear cytology code and the separately identifiable HPV reflex test code may both be reported, since reflex testing (as already established generally) is coded when it actually occurs based on the triggering result, representing a genuinely distinct additional laboratory test');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26148d07-7e4b-4171-b659-4fd4bf60c321', 'aa4c3f67-4bb9-4810-8da9-9192955bdf8f', 1, 'Reflex HPV testing is always bundled into the Pap smear code with no separate reporting possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09a0643d-9167-4677-95ec-69fe34a06d19', 'aa4c3f67-4bb9-4810-8da9-9192955bdf8f', 2, 'ASC-US results never trigger any separately codeable reflex testing under any laboratory protocol');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae3a0480-2572-4099-a7eb-07235c925b5f', 'aa4c3f67-4bb9-4810-8da9-9192955bdf8f', 3, 'HPV testing following an abnormal Pap result is coded identically to the original Pap smear code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be950505-17df-4fae-8a88-d581281e5dbf', '2ea4e023-46d3-4354-93e8-ef26e15311fa', 0, 'The culture code itself is reported based on the testing actually performed (incubation and monitoring for growth), regardless of whether the result is positive or negative — a negative (''no growth'') result doesn''t mean the culture procedure itself wasn''t performed and isn''t codeable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e705d56a-1f6f-4b42-be72-6643119dd98c', '2ea4e023-46d3-4354-93e8-ef26e15311fa', 1, 'A negative culture result is never separately coded since ''nothing was found''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed028f97-c5be-41c6-b6a6-a9d7d8e9d2ac', '2ea4e023-46d3-4354-93e8-ef26e15311fa', 2, 'Only positive culture results are ever billable; negative results require the lab to absorb the cost with no code reported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c8879de-1b71-41f3-902a-d3e4a058832c', '2ea4e023-46d3-4354-93e8-ef26e15311fa', 3, 'Negative and positive culture results require entirely different code sets unrelated to each other');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07c4b174-cc81-44bc-ab23-a8113c890b98', '5ece245e-b357-47f5-b623-15394f84cb13', 0, 'Molecular pathology testing for specific gene mutations has its own specific code(s) (often per-gene, per the Tier 1/Tier 2 molecular pathology structure already discussed), distinct from routine chemistry or histopathology codes, reflecting the specialized nature of genomic/molecular testing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f44fa487-a4d6-497b-93a4-b9a4acad8060', '5ece245e-b357-47f5-b623-15394f84cb13', 1, 'Gene mutation testing is coded identically to a routine complete blood count');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('325fb792-578d-470e-a9e3-2da5a1673beb', '5ece245e-b357-47f5-b623-15394f84cb13', 2, 'Molecular pathology testing has no distinct CPT code and must always use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22856de6-943a-466b-930b-160c0f4299ad', '5ece245e-b357-47f5-b623-15394f84cb13', 3, 'Gene mutation testing for targeted therapy selection is coded using the same code as a surgical pathology specimen examination');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53b8d3d9-36c5-4701-b1ed-8bf00875bcbe', 'ab5e824f-36f1-469f-a48c-4e97cab8a746', 0, 'IHC staining has its own specific code(s), generally reported per separately identifiable antibody/stain performed, distinct from the routine H&E (hematoxylin and eosin) staining included in standard surgical pathology examination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c5dc532-191e-4131-86f4-2da17def2b11', 'ab5e824f-36f1-469f-a48c-4e97cab8a746', 1, 'IHC staining is always included in the base surgical pathology examination code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fecf90e0-eca9-452f-87df-fba39ebbfa2a', 'ab5e824f-36f1-469f-a48c-4e97cab8a746', 2, 'IHC testing is coded identically to a molecular pathology gene mutation test');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e81c6a9-b3e8-419e-978f-5baa12992320', 'ab5e824f-36f1-469f-a48c-4e97cab8a746', 3, 'Only one IHC stain code exists regardless of how many distinct antibodies/stains are performed on a specimen');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8a9337c-10ac-4663-8e00-f481c1b3b4c1', '7eaf6cb3-5ec4-4737-9004-766d6822a1fd', 0, 'Always select the single most comprehensive-sounding code available regardless of which specific individual tests were actually performed and documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('988c62fd-ab52-4ce2-8ea7-7d0275de3995', '7eaf6cb3-5ec4-4737-9004-766d6822a1fd', 1, 'Carefully verify which SPECIFIC individual tests/components were actually performed (matching against defined panel component lists, reflex-test triggers, specific stains/antibodies, or specific gene targets) rather than assuming a broad or bundled code applies without confirming its specific defined scope was fully met');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0824a5e9-b1aa-4fa8-ab55-f7005fa2aca5', '7eaf6cb3-5ec4-4737-9004-766d6822a1fd', 2, 'Assume all laboratory codes within the same specimen type (e.g., ''blood'' or ''tissue'') are interchangeable regardless of the specific test performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc61288d-771b-4109-ab00-83f943eacacf', '7eaf6cb3-5ec4-4737-9004-766d6822a1fd', 3, 'Rely solely on the ordering physician''s requisition form''s code selection without independently verifying it against what was actually performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d5f7e5d-1c56-4946-be06-300b844e528a', '095bbafe-25c3-4d92-9e07-9bad1b69188b', 0, 'CPT includes specific ESRD-related monthly capitation-type codes (age-stratified in some structures) covering routine dialysis-related physician services for a full month, distinct from coding each individual dialysis session separately as would occur in an inpatient, non-ESRD-program context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3756602c-29e1-4eb8-a3e7-a5c966028ff0', '095bbafe-25c3-4d92-9e07-9bad1b69188b', 1, 'Outpatient ESRD dialysis is coded identically to inpatient hemodialysis session-by-session coding discussed for CCS/ICD-10-PCS purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87d50eea-691c-4dd9-ac48-6a77923bac8b', '095bbafe-25c3-4d92-9e07-9bad1b69188b', 2, 'ESRD monthly dialysis services have no distinct CPT code structure from a single outpatient office visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ae4c6f5-1d3a-4022-bff9-006651606e0f', '095bbafe-25c3-4d92-9e07-9bad1b69188b', 3, 'Only the dialysis facility, never the physician, has any billable CPT service related to ESRD monthly management');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5013709-9859-4bfe-81d2-5da55c388c0a', '8cbd1027-5b42-41c1-8155-d1fdd1f4c0bf', 0, 'CPT includes a distinct Ophthalmology code family (intermediate and comprehensive exam codes) that may be used as an alternative to general E/M codes for eye-focused visits, reflecting the specialty''s own established examination/coding convention, subject to correct code selection based on documented exam elements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f6fcf73-2f53-4c3a-a11b-ade4a757f138', '8cbd1027-5b42-41c1-8155-d1fdd1f4c0bf', 1, 'Ophthalmological services can only ever be coded using general E/M codes, with no distinct ophthalmology-specific code family');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cf6adb1-5a92-4179-87c7-7faecc6d37f9', '8cbd1027-5b42-41c1-8155-d1fdd1f4c0bf', 2, 'Ophthalmology codes and general E/M codes are always used together for the same single visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c8205d8-b28d-4d5e-a7de-13e6691dc19f', '8cbd1027-5b42-41c1-8155-d1fdd1f4c0bf', 3, 'Ophthalmological exam codes are selected solely based on the patient''s visual acuity score');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf3bdc97-a715-4652-ba4e-4c28069534be', 'c7da859e-23ab-4cea-aca0-2255dba88298', 0, 'These diagnostic imaging/testing procedures generally have their own specific CPT codes, separately reportable in addition to the eye examination code (ophthalmology E/M-alternative code or general E/M code), since they represent distinct diagnostic testing services beyond the examination itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59a15d77-4173-4809-898b-adf1f01555b1', 'c7da859e-23ab-4cea-aca0-2255dba88298', 1, 'Fundus photography and OCT are always bundled into the eye exam code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abfea98b-4603-474b-b3d5-799e40ab1104', 'c7da859e-23ab-4cea-aca0-2255dba88298', 2, 'These tests are coded using the same code as a general X-ray');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d199c650-dc6f-4c91-ad0a-3e6830c9c3de', 'c7da859e-23ab-4cea-aca0-2255dba88298', 3, 'OCT and fundus photography are coded identically to each other with no distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('579ec80e-013c-41dd-b3f1-54c75b6b87e4', 'dee8eef5-c49b-4e1f-9790-22b2b0535839', 0, 'The injection PROCEDURE has its own specific CPT code, with the medication/drug itself separately reportable via an appropriate HCPCS Level II drug code — reflecting the same procedure-plus-drug-product separation pattern already established for vaccines and other injected/administered medications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d9a8e86-731d-4a68-8e43-24b22cf49d5e', 'dee8eef5-c49b-4e1f-9790-22b2b0535839', 1, 'The injection and the drug are always combined into one single code with no separate reporting of either component');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9d8871d-0d0a-4eaa-9b6c-b15d323b3e17', 'dee8eef5-c49b-4e1f-9790-22b2b0535839', 2, 'Intravitreal injections are coded using the same code as a routine intramuscular injection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dbac9116-289c-4fa8-9a32-b072e80f0fa8', 'dee8eef5-c49b-4e1f-9790-22b2b0535839', 3, 'The drug product is never separately billable for intravitreal injections regardless of payer policy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fac8f01a-4220-4d3a-aab5-913290ad92e6', '35f4dd24-3d48-48bf-b2f9-5af27c21157e', 0, 'Cardiac rehabilitation has its own specific CPT codes reflecting monitored exercise/education sessions over a defined program, generally billed per session and distinct from a general E/M visit code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89012df4-7d4f-4401-905a-88193d911eb7', '35f4dd24-3d48-48bf-b2f9-5af27c21157e', 1, 'Cardiac rehabilitation is billed using the same codes as a general physical therapy timed code, with no cardiac-specific distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26077533-87c1-4867-9e1e-9f00f6550fa1', '35f4dd24-3d48-48bf-b2f9-5af27c21157e', 2, 'Cardiac rehabilitation cannot be separately coded from a routine cardiology follow-up E/M visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f790a469-71d1-47b4-b27c-0ff3dea6d337', '35f4dd24-3d48-48bf-b2f9-5af27c21157e', 3, 'Cardiac rehabilitation codes require inpatient hospitalization to be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('824cfc15-e866-45a6-9c58-c69fade737ca', '981d730a-c099-45ea-bb88-9ed8a07040c4', 0, 'Both services may potentially be separately reportable if each is separately identifiable and medically necessary in its own right, with correct modifier use (e.g., modifier 25 on the E/M service) as appropriate — following the same general same-day-multiple-service principles already established for other E/M-plus-other-service combinations (e.g., E/M plus preventive visit)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60014135-e866-416b-b51b-18f305521b97', '981d730a-c099-45ea-bb88-9ed8a07040c4', 1, 'Only one of the two services may ever be billed on the same date, regardless of medical necessity for both');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc6ea951-a9c9-43c6-a44a-0d76aa858bfc', '981d730a-c099-45ea-bb88-9ed8a07040c4', 2, 'Cardiac rehabilitation always requires a separate calendar day from any E/M visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71a8f724-b437-42e3-9111-702a44a29bed', '981d730a-c099-45ea-bb88-9ed8a07040c4', 3, 'E/M and cardiac rehabilitation are always bundled into a single combined code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b3a0c09-75f0-43a3-92b6-a3de80fa55ab', '96776d16-478f-4cc9-a10a-1717ca23066c', 0, 'Both the eye exam code and the OCT code may be separately reportable when each is genuinely, separately medically necessary and documented, consistent with the general same-day-multiple-distinct-service principle already established elsewhere');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce77e2f8-5894-43e6-9eb8-5f34c870413f', '96776d16-478f-4cc9-a10a-1717ca23066c', 1, 'Only one of the two services may ever be billed on the same date regardless of medical necessity for both');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('645c241f-8fee-4ed7-b0c8-16d390467682', '96776d16-478f-4cc9-a10a-1717ca23066c', 2, 'OCT is always bundled into the eye exam code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b686044e-8639-492a-98c9-5ab603c02f32', '96776d16-478f-4cc9-a10a-1717ca23066c', 3, 'The two services must always be performed on different calendar days to both be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39730706-956f-416a-9bd5-b82ea808f7ce', '1748397a-bad9-486e-b983-b0856e5650ab', 0, 'Different phases of cardiac rehabilitation may have different coding/coverage treatment, since Phase II (monitored, immediately post-cardiac-event) and Phase III (longer-term maintenance) reflect genuinely different program structures and, often, different payer coverage policies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5aad65e1-4480-4108-9dbe-2a1ee856925f', '1748397a-bad9-486e-b983-b0856e5650ab', 1, 'All phases of cardiac rehabilitation are coded and covered identically regardless of the specific phase/timing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('edfa9f6f-c2c8-4036-9183-33cf07c24472', '1748397a-bad9-486e-b983-b0856e5650ab', 2, 'Only Phase III maintenance programs have any CPT code; Phase II has no distinct coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e5f277d-1493-4611-8059-3ed8697886b0', '1748397a-bad9-486e-b983-b0856e5650ab', 3, 'Cardiac rehabilitation phase has no bearing on CPT code selection or payer coverage');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87993fb4-b001-4d52-a06b-2169580e1dd6', 'a66582f4-89e9-48bd-a4fa-40cbd2876db7', 0, 'Pulmonary rehabilitation has its own specific CPT code(s) reflecting monitored exercise/education sessions for patients with chronic respiratory conditions, structurally paralleling the cardiac rehabilitation code family''s session-based approach but representing a distinct code set for a different condition category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e8814be-b548-4421-a584-b93a3e1e33c5', 'a66582f4-89e9-48bd-a4fa-40cbd2876db7', 1, 'Pulmonary rehabilitation is billed using the identical codes as cardiac rehabilitation, with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed3e17ec-b5cf-489b-8fb3-4878294417ff', 'a66582f4-89e9-48bd-a4fa-40cbd2876db7', 2, 'Pulmonary rehabilitation cannot be separately coded from a routine pulmonology follow-up visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33cf82d1-3915-43f6-b0c9-0bc20f98da82', 'a66582f4-89e9-48bd-a4fa-40cbd2876db7', 3, 'Pulmonary rehabilitation codes require inpatient hospitalization to be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a4cab37-84f3-4f50-82f1-2c117ad1412e', 'b6435399-7224-4b68-880d-1c12508b961b', 0, 'Always default to a general office visit E/M code whenever a Medicine-section code seems unclear, regardless of what service was actually documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6bbd502-45f5-4641-ac63-71c650d9152e', 'b6435399-7224-4b68-880d-1c12508b961b', 1, 'Carefully identify the SPECIFIC service structure actually documented (monthly capitation vs. per-session, time-based vs. flat-fee, product-plus-administration split, or specific program/phase type) and match it to the Medicine-section code family reflecting that specific structure, since Medicine-section codes vary considerably in their underlying billing-structure logic across different service types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a728bbe8-2f7a-4e81-a61d-8ada0a13f348', 'b6435399-7224-4b68-880d-1c12508b961b', 2, 'Assume all Medicine-section services are billed as flat per-visit fees with no structural variation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d04e8eb-6235-4851-bffb-bef417ce812c', 'b6435399-7224-4b68-880d-1c12508b961b', 3, 'Rely on the department/specialty performing the service alone, without confirming the actual service structure documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cbf50e7-b983-4a8e-a658-7dd1d3252180', '5d6b92f1-30a4-44dc-80e3-26478c5fedc1', 0, 'An ABN informs a Medicare beneficiary in advance that a specific service may not be covered, with related modifiers indicating whether a valid ABN is on file and the reason for expected non-coverage — these modifiers communicate the ABN/coverage-expectation status of a claim line, not a clinical distinctness concept like modifier 59');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98fd72c0-d888-4e51-908b-e4ae8793c9be', '5d6b92f1-30a4-44dc-80e3-26478c5fedc1', 1, 'ABN-related modifiers indicate that two surgeons performed a procedure together');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c83a26c7-fe53-4ae8-ac4b-343978920cda', '5d6b92f1-30a4-44dc-80e3-26478c5fedc1', 2, 'ABN modifiers are used exclusively for anesthesia claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b0a9bb2-b485-4bd7-ac3a-c2da5ff87ec1', '5d6b92f1-30a4-44dc-80e3-26478c5fedc1', 3, 'ABN-related modifiers replace the need for any diagnosis code on the claim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4564034-181a-4753-9d76-244104b870a4', '1bc156ee-248b-4bcb-9266-0ac534b64b8d', 0, 'Indicates a required ABN was issued for the item/service, in accordance with payer policy, in case the item/service is denied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bff03579-f64e-479c-a427-34e59ff9311a', '1bc156ee-248b-4bcb-9266-0ac534b64b8d', 1, 'Indicates the service was performed by an assistant surgeon');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67e65e99-6143-4e4f-b7a2-ef790386939e', '1bc156ee-248b-4bcb-9266-0ac534b64b8d', 2, 'Indicates a bilateral procedure was performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1cd2470-da03-4c40-9f6d-115aaae18b18', '1bc156ee-248b-4bcb-9266-0ac534b64b8d', 3, 'Indicates a repeat clinical laboratory test');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1723220e-8c7a-4b45-b7ca-15a133e5e109', '1d2ace40-70b5-498c-946d-f36b44d71194', 0, 'GZ indicates an item/service is expected to be denied as not reasonable and necessary, and no ABN was obtained — signaling the provider''s own expectation of non-coverage without proper advance beneficiary notice, which carries billing-compliance implications regarding beneficiary financial liability');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9bf4f96-fea4-4a42-9c4d-18162e96a1bd', '1d2ace40-70b5-498c-946d-f36b44d71194', 1, 'GZ indicates a bilateral procedure with no ABN relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('776683a2-f993-4030-ba81-185966dc5550', '1d2ace40-70b5-498c-946d-f36b44d71194', 2, 'GZ is used only for laboratory panel codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28bc02e0-f9ea-49a9-a9c0-4762c5dbd32c', '1d2ace40-70b5-498c-946d-f36b44d71194', 3, 'GZ modifiers guarantee full payment regardless of medical necessity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f551911-16f5-48d3-b626-88e9a8015fa5', '91f57baf-6bba-49a3-b968-35567bbf54f8', 0, 'Telehealth modifiers themselves address MODALITY (how a service was delivered), which is a separate concept from NCCI''s code-PAIR bundling edits — a service can require both a telehealth modality modifier AND, separately, an NCCI-bypass modifier (like 59) if the specific code combination and clinical circumstances call for both');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a43ef4b-5d2d-433f-8e0c-93a75cec5db5', '91f57baf-6bba-49a3-b968-35567bbf54f8', 1, 'Telehealth modifiers automatically bypass all NCCI edits for any code reported alongside them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f17a479f-a021-427a-8756-f48fd1f9b986', '91f57baf-6bba-49a3-b968-35567bbf54f8', 2, 'Telehealth modifiers and NCCI-bypass modifiers can never both apply to the same claim line');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e873694-c0e3-4da9-a198-4da05aa13264', '91f57baf-6bba-49a3-b968-35567bbf54f8', 3, 'NCCI edits do not apply to any telehealth-delivered service under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('999d30b0-9050-4544-a6e2-a2ce33c80fd1', '2ef022ea-2cc9-4f00-ad45-1c5b08742b57', 0, 'Reflexively applying a bypass modifier without genuine clinical-distinctness support (rather than reviewing whether the specific clinical circumstances actually justify it) is the exact compliance risk pattern already discussed regarding modifier 59/NCCI misuse — a denied claim doesn''t itself establish that a bypass modifier is appropriate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97f002e6-863c-4c36-8680-0a07db209997', '2ef022ea-2cc9-4f00-ad45-1c5b08742b57', 1, 'Modifier 59 should always be applied to any denied claim regardless of the underlying clinical facts, since appeal success rates are the only relevant consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6fce4c7-4fed-4a71-af5f-180dcca67382', '2ef022ea-2cc9-4f00-ad45-1c5b08742b57', 2, 'NCCI edits are always incorrect and should be bypassed whenever technically possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27bfb5ea-d24f-4b9c-be3a-6affffcb584f', '2ef022ea-2cc9-4f00-ad45-1c5b08742b57', 3, 'Claim denials always indicate a coding error requiring an NCCI bypass modifier, with no other possible explanation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('322a21a7-910c-4f34-957d-03f827659b40', '85ad44f2-61c0-4cf7-9e5e-7914e2d9ab5a', 0, 'Verifying that the documentation supports both the telehealth modality (place of service/modifier consistency) AND the modifier 25 justification (a genuinely significant, separately identifiable E/M service beyond another same-day service) independently, since each modifier addresses a distinct compliance question requiring its own documentation support');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('451b9499-6f97-478d-9d1f-354884a1bdb5', '85ad44f2-61c0-4cf7-9e5e-7914e2d9ab5a', 1, 'Assuming that using a telehealth modifier automatically also justifies modifier 25 without independent review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c723eea0-70d8-45f1-8db6-62727fd565ab', '85ad44f2-61c0-4cf7-9e5e-7914e2d9ab5a', 2, 'Telehealth and modifier 25 can never both be used on the same claim under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('51ba2588-4887-4f58-bad1-7d07ab1ad959', '85ad44f2-61c0-4cf7-9e5e-7914e2d9ab5a', 3, 'Only one of the two modifiers should ever be reviewed for documentation support, with the other assumed compliant automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50760f84-2387-440b-afe6-62a3df0c0740', '1dbb6a2a-87b8-4253-9d82-37c630cbadeb', 0, 'Ensuring documentation clearly supports the specific requirements of these codes (e.g., verbal/internet consultation with a treating provider, the consultant''s own time, no face-to-face contact with the patient by the consultant) helps avoid miscoding a service that doesn''t actually meet the interprofessional consultation code''s specific structural requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cc7486e-8bba-40d4-adeb-ae2bda310cdd', '1dbb6a2a-87b8-4253-9d82-37c630cbadeb', 1, 'Interprofessional consultation codes require no specific documentation beyond a general progress note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f58bb3dd-9a5f-44c4-a9a0-70e28ec5b36a', '1dbb6a2a-87b8-4253-9d82-37c630cbadeb', 2, 'These codes are interchangeable with a standard telehealth E/M visit code, requiring no distinct documentation review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec08cdf4-fbff-42bc-92f2-04c1a4a13058', '1dbb6a2a-87b8-4253-9d82-37c630cbadeb', 3, 'Newer/less familiar code families never warrant any particular documentation-compliance attention');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a5199f4-f32f-4d31-ad62-b1439ff89efa', '8613a89d-6eb0-4b51-983b-3c8f5b3d6f7c', 0, 'Given that RPM/CCM codes are billed on a recurring (often monthly) basis for non-face-to-face time/activities that may be harder to independently verify than a discrete, single face-to-face visit, maintaining clear, contemporaneous time/activity documentation is particularly important to support ongoing compliant billing of these code families');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20e35331-acaa-45e0-9140-3a2dbc8c80c9', '8613a89d-6eb0-4b51-983b-3c8f5b3d6f7c', 1, 'RPM/CCM codes require no specific documentation since they are billed as a flat fee with no verification ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d47b2b0-4c1b-45e8-a710-c1f169e3eb7b', '8613a89d-6eb0-4b51-983b-3c8f5b3d6f7c', 2, 'Only face-to-face, in-person services ever warrant any documentation-compliance attention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d116cca-614c-49b1-b8cf-a1cff49a7ea8', '8613a89d-6eb0-4b51-983b-3c8f5b3d6f7c', 3, 'RPM/CCM billing compliance is identical in every respect to billing a single E/M office visit, with no distinct considerations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('094730e3-8d6c-4163-9991-8f8dd74d0aef', '36040163-94c9-46c6-b253-2c2078cd87af', 0, 'GX indicates a voluntary ABN was issued for a service that is statutorily excluded from Medicare coverage or does not meet the definition of a Medicare benefit (not merely ''not medically necessary''), whereas GA indicates a required ABN issued because a service is expected to be denied as not reasonable/necessary');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('475d108f-e3f0-49c2-adc2-812f967d5b43', '36040163-94c9-46c6-b253-2c2078cd87af', 1, 'GX and GA are fully interchangeable with no distinction in meaning');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30cf2188-b81b-48b1-9f86-2412725fbebb', '36040163-94c9-46c6-b253-2c2078cd87af', 2, 'GX applies only to laboratory codes, never any other service type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70550f6b-81b4-45d4-ba83-92ad2518f35f', '36040163-94c9-46c6-b253-2c2078cd87af', 3, 'GX indicates a bilateral procedure was performed with an ABN on file');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40268824-72c2-445d-9338-0e336eaa7491', '17e5b97c-a075-400e-bf53-353f219ce0a6', 0, 'Always apply the modifier most likely to result in the highest reimbursement, regardless of which modifier actually, accurately describes the documented circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26d57c0e-ff36-4da2-b971-3bf1c665d63c', '17e5b97c-a075-400e-bf53-353f219ce0a6', 1, 'Identify what SPECIFIC circumstance actually occurred and is documented (staged procedure, unrelated postoperative service, bilateral procedure, telehealth delivery, ABN status, genuine clinical distinctness) and select the modifier whose specific defined meaning accurately matches that documented circumstance — since each modifier addresses a distinct, specific coding question rather than being a generic, interchangeable reimbursement tool');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38ef37bc-4b94-4031-8625-ae0167d34b18', '17e5b97c-a075-400e-bf53-353f219ce0a6', 2, 'Assume modifiers are optional stylistic additions with no effect on claim adjudication or compliance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fe3161f-1a98-4b88-a62f-348a3bebc677', '17e5b97c-a075-400e-bf53-353f219ce0a6', 3, 'Apply as many modifiers as possible to every claim line to maximize the chance of correct adjudication');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
